const permissions = {
  viewer: ["read"],
  editor: ["read", "write"],
  admin: ["read", "write", "delete"],
};
function can(role, action) {
  return permissions[role].includes(action);
}
console.log(can("editor", "delete"));
console.log(can("admin", "delete"));
console.log(can("viewer", "read"));

